import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline


_cpp_decl = r"""
#include <torch/extension.h>

torch::Tensor cute_layer_norm(
    torch::Tensor x,
    torch::Tensor weight,
    torch::Tensor bias,
    double eps);
"""


_cuda_src = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <c10/cuda/CUDAStream.h>
#include <limits>
#include <cute/tensor.hpp>

// CUTE names are qualified explicitly to avoid nvcc anonymous-namespace collisions.

namespace {

constexpr int kThreads = 256;

__global__ void cute_layer_norm_kernel(
    const float* __restrict__ x,
    const float* __restrict__ weight,
    const float* __restrict__ bias,
    float* __restrict__ out,
    int64_t rows,
    int64_t normalized_size,
    float eps)
{
    const int row = static_cast<int>(blockIdx.x);
    const int tid = threadIdx.x;

    if (row >= rows) {
        return;
    }

    const int64_t row_offset = static_cast<int64_t>(row) * normalized_size;

    auto gx = cute::make_tensor(
        cute::make_gmem_ptr(x + row_offset),
        cute::make_shape(normalized_size),
        cute::make_stride(cute::Int<1>{}));
    auto gw = cute::make_tensor(
        cute::make_gmem_ptr(weight),
        cute::make_shape(normalized_size),
        cute::make_stride(cute::Int<1>{}));
    auto gb = cute::make_tensor(
        cute::make_gmem_ptr(bias),
        cute::make_shape(normalized_size),
        cute::make_stride(cute::Int<1>{}));
    auto go = cute::make_tensor(
        cute::make_gmem_ptr(out + row_offset),
        cute::make_shape(normalized_size),
        cute::make_stride(cute::Int<1>{}));
    extern __shared__ double reduction[];
    double* sums = reduction;
    double* sumsq = reduction + kThreads;

    double local_sum = 0.0;
    double local_sumsq = 0.0;

    for (int64_t i = tid; i < normalized_size; i += blockDim.x) {
        const double v = static_cast<double>(gx(i));
        local_sum += v;
        local_sumsq += v * v;
    }

    sums[tid] = local_sum;
    sumsq[tid] = local_sumsq;
    __syncthreads();

    for (int stride = kThreads / 2; stride > 0; stride >>= 1) {
        if (tid < stride) {
            sums[tid] += sums[tid + stride];
            sumsq[tid] += sumsq[tid + stride];
        }
        __syncthreads();
    }

    const double mean = sums[0] / static_cast<double>(normalized_size);
    double variance =
        sumsq[0] / static_cast<double>(normalized_size) - mean * mean;

    if (variance < 0.0) {
        variance = 0.0;
    }

    const double inv_std = rsqrt(variance + static_cast<double>(eps));

    for (int64_t i = tid; i < normalized_size; i += blockDim.x) {
        const double normalized =
            (static_cast<double>(gx(i)) - mean) * inv_std;
        go(i) = static_cast<float>(
            normalized * static_cast<double>(gw(i)) +
            static_cast<double>(gb(i)));
    }
}

} // namespace

torch::Tensor cute_layer_norm(
    torch::Tensor x,
    torch::Tensor weight,
    torch::Tensor bias,
    double eps)
{
    TORCH_CHECK(x.is_cuda(), "x must be a CUDA tensor");
    TORCH_CHECK(weight.is_cuda(), "weight must be a CUDA tensor");
    TORCH_CHECK(bias.is_cuda(), "bias must be a CUDA tensor");

    TORCH_CHECK(
        x.scalar_type() == at::kFloat &&
        weight.scalar_type() == at::kFloat &&
        bias.scalar_type() == at::kFloat,
        "cute_layer_norm currently expects float32 tensors");

    TORCH_CHECK(x.dim() >= 1, "x must have at least one dimension");
    TORCH_CHECK(weight.dim() == 1, "weight must be one-dimensional");
    TORCH_CHECK(bias.dim() == 1, "bias must be one-dimensional");
    TORCH_CHECK(
        weight.numel() == bias.numel(),
        "weight and bias must have the same number of elements");

    const int64_t normalized_size = weight.numel();
    TORCH_CHECK(normalized_size > 0,
                "normalized size must be positive");
    TORCH_CHECK(
        x.numel() % normalized_size == 0,
        "The input size must be divisible by the normalized size");

    auto x_contiguous = x.contiguous();
    auto weight_contiguous = weight.contiguous();
    auto bias_contiguous = bias.contiguous();
    auto out = torch::empty_like(x_contiguous);

    const int64_t rows = x_contiguous.numel() / normalized_size;

    TORCH_CHECK(rows <= static_cast<int64_t>(std::numeric_limits<int>::max()),
                "Too many rows for the CUDA grid");

    cudaStream_t stream = c10::cuda::getCurrentCUDAStream().stream();

    cute_layer_norm_kernel<<<
        static_cast<unsigned int>(rows),
        kThreads,
        2 * kThreads * sizeof(double),
        stream>>>(
        x_contiguous.data_ptr<float>(),
        weight_contiguous.data_ptr<float>(),
        bias_contiguous.data_ptr<float>(),
        out.data_ptr<float>(),
        rows,
        normalized_size,
        static_cast<float>(eps));

    TORCH_CHECK(
        cudaGetLastError() == cudaSuccess,
        "cute_layer_norm_kernel launch failed");

    return out;
}
"""


_cute_ext = load_inline(
    name="cute_layer_norm_ext",
    cpp_sources=_cpp_decl,
    cuda_sources=_cuda_src,
    functions=["cute_layer_norm"],
    extra_cflags=["-O3"],
    extra_cuda_cflags=[
        "-O3",
        "-I/root/cutegen_test/cutegen/cutlass/include",
    ],
    verbose=False,
)


class ModelNew(nn.Module):
    def __init__(self, normalized_shape: tuple):
        super().__init__()
        self.ln = nn.LayerNorm(normalized_shape=normalized_shape)

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        normalized_size = self.ln.weight.numel()
        x_view = x.reshape(-1, normalized_size)

        return _cute_ext.cute_layer_norm(
            x_view,
            self.ln.weight.reshape(-1),
            self.ln.bias.reshape(-1),
            self.ln.eps,
        ).reshape_as(x)

